namespace jxx::awt::internal {BufferedImageGraphics2D::BufferedImageGraphics2D(const ::jxx::Ptr<::jxx::awt::image::BufferedImage>&i):Graphics2D(),image_(i){} ::jxx::Ptr<::jxx::awt::Graphics> BufferedImageGraphics2D::create()const{return ::jxx::NEW<BufferedImageGraphics2D>(image_);} void BufferedImageGraphics2D::translate(int x,int y){tx_+=x;ty_+=y;} bool BufferedImageGraphics2D::drawImage(const ::jxx::Ptr<Image>&src,int x,int y,const ::jxx::Ptr<::jxx::awt::image::ImageObserver>&){auto b=::jxx::CAST<::jxx::awt::image::BufferedImage>(src);if(!b||!image_)return false;for(int yy=0;yy<b->getHeight(nullptr);++yy)for(int xx=0;xx<b->getWidth(nullptr);++xx){int dx=x+tx_+xx,dy=y+ty_+yy;if(dx>=0&&dy>=0&&dx<image_->getWidth(nullptr)&&dy<image_->getHeight(nullptr))image_->setRGB(dx,dy,b->getRGB(xx,yy));}return true;}}
